<body>
  <div id="game-container">
    <div id="instructions">
      <strong>Billiards</strong><br>
      Drag back from the white cue ball to aim and set power, then release to shoot.<br>
      <button id="reset-btn">Reset / Rack</button>
    </div>
    <canvas id="table"></canvas>
  </div>
<script>
(() => {
  const W = 800;
  const H = 400;
  const R = 10;
  const OFFSET = 20;
  const PR = 18; // Pocket capture radius
  const FRICTION = 150; // px/s^2
  const WALL_E = 0.95; // Wall restitution
  const BALL_E = 0.99; // Ball restitution (near-elastic)
  const MAX_DRAG = 200; // Pixels for max pull
  const MAX_SPEED = 1500; // Max shot speed px/s

  const pockets = [
    {x: 0, y: 0},
    {x: W/2, y: 0},
    {x: W, y: 0},
    {x: 0, y: H},
    {x: W/2, y: H},
    {x: W, y: H}
  ];

  const COLORS = ['#f00', '#ffa500', '#ff0', '#0f0', '#00f', '#4b0082', '#ee82ee', '#f00', '#ffa500', '#ff0', '#0f0', '#00f', '#4b0082', '#ee82ee', '#f00'];

  let internalBalls = [];
  let isDragging = false;
  let dragCurrent = null;
  let animId = null;
  let lastTime = null;

  const canvas = document.getElementById('table');
  canvas.width = W + OFFSET * 2;
  canvas.height = H + OFFSET * 2;
  const ctx = canvas.getContext('2d');

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Table wood
    ctx.fillStyle = '#5c4033';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // Felt
    ctx.fillStyle = '#0b6623';
    ctx.fillRect(OFFSET, OFFSET, W, H);
    // Cushion border
    ctx.strokeStyle = '#064d18';
    ctx.lineWidth = 6;
    ctx.strokeRect(OFFSET, OFFSET, W, H);
    // Pockets
    ctx.fillStyle = '#000';
    for (let p of pockets) {
      ctx.beginPath();
      ctx.arc(OFFSET + p.x, OFFSET + p.y, PR, 0, Math.PI * 2);
      ctx.fill();
    }
    // Balls
    for (let b of internalBalls) {
      if (b.potted) continue;
      ctx.beginPath();
      ctx.arc(OFFSET + b.x, OFFSET + b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color || '#fff';
      ctx.fill();
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1;
      ctx.stroke();
      // Highlight
      ctx.beginPath();
      ctx.arc(OFFSET + b.x - R/3, OFFSET + b.y - R/3, R/3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();
    }
    // Aim line while dragging
    if (isDragging && dragCurrent) {
      let cue = internalBalls.find(b => b.cue && !b.potted);
      if (cue) {
        let dx = cue.x - dragCurrent.x;
        let dy = cue.y - dragCurrent.y;
        let dist = Math.hypot(dx, dy);
        if (dist > 0) {
          // Pull-back line
          ctx.beginPath();
          ctx.moveTo(OFFSET + cue.x, OFFSET + cue.y);
          ctx.lineTo(OFFSET + dragCurrent.x, OFFSET + dragCurrent.y);
          ctx.strokeStyle = 'rgba(255,255,255,0.5)';
          ctx.lineWidth = 2;
          ctx.stroke();
          // Aim direction line
          let aimLen = Math.min(dist * 2, 300);
          ctx.beginPath();
          ctx.moveTo(OFFSET + cue.x, OFFSET + cue.y);
          ctx.lineTo(OFFSET + cue.x + (dx/dist)*aimLen, OFFSET + cue.y + (dy/dist)*aimLen);
          ctx.strokeStyle = 'rgba(255,255,0,0.8)';
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }
    }
  }

  window.sim = {
    W: W,
    H: H,
    R: R,
    reset: function(balls) {
      internalBalls = balls.map((b, i) => ({
        x: b.x,
        y: b.y,
        vx: typeof b.vx === 'number' ? b.vx : 0,
        vy: typeof b.vy === 'number' ? b.vy : 0,
        cue: !!b.cue,
        potted: false,
        color: b.cue ? '#fff' : COLORS[i % COLORS.length]
      }));
      draw();
    },
    step: function(dt) {
      if (dt <= 0) { draw(); return; }
      let maxV = 0;
      for (let b of internalBalls) {
        if (!b.potted) maxV = Math.max(maxV, Math.hypot(b.vx, b.vy));
      }
      // Dynamic substepping to prevent tunneling and ensure determinism
      let substeps = Math.ceil((maxV * dt) / 5);
      if (substeps < 10) substeps = 10;
      if (substeps > 1000) substeps = 1000;
      let sdt = dt / substeps;

      for (let s = 0; s < substeps; s++) {
        // 1. Update positions
        for (let b of internalBalls) {
          if (b.potted) continue;
          b.x += b.vx * sdt;
          b.y += b.vy * sdt;
        }
        // 2. Friction
        for (let b of internalBalls) {
          if (b.potted) continue;
          let speed = Math.hypot(b.vx, b.vy);
          if (speed > 0) {
            let drop = FRICTION * sdt;
            let newSpeed = Math.max(0, speed - drop);
            b.vx = (b.vx / speed) * newSpeed;
            b.vy = (b.vy / speed) * newSpeed;
          }
        }
        // 3. Pockets
        for (let b of internalBalls) {
          if (b.potted) continue;
          for (let p of pockets) {
            if (Math.hypot(b.x - p.x, b.y - p.y) < PR) {
              b.potted = true;
              b.vx = 0; b.vy = 0;
              b.x = p.x; b.y = p.y;
              break;
            }
          }
        }
        // 4. Ball-to-ball collisions
        for (let i = 0; i < internalBalls.length; i++) {
          for (let j = i + 1; j < internalBalls.length; j++) {
            let b1 = internalBalls[i], b2 = internalBalls[j];
            if (b1.potted || b2.potted) continue;
            let dx = b2.x - b1.x, dy = b2.y - b1.y;
            let dist = Math.hypot(dx, dy);
            if (dist < 2*R) {
              if (dist === 0) { dx = 1; dy = 0; dist = 1; }
              let nx = dx / dist, ny = dy / dist;
              let overlap = 2*R - dist;
              // Separate
              b1.x -= nx * overlap / 2;
              b1.y -= ny * overlap / 2;
              b2.x += nx * overlap / 2;
              b2.y += ny * overlap / 2;
              // Resolve velocity
              let dvx = b1.vx - b2.vx, dvy = b1.vy - b2.vy;
              let vn = dvx * nx + dvy * ny;
              if (vn > 0) {
                let imp = vn * BALL_E;
                b1.vx -= imp * nx;
                b1.vy -= imp * ny;
                b2.vx += imp * nx;
                b2.vy += imp * ny;
              }
            }
          }
        }
        // 5. Cushions
        for (let b of internalBalls) {
          if (b.potted) continue;
          if (b.x < R) { b.x = R; b.vx = Math.abs(b.vx) * WALL_E; }
          else if (b.x > W - R) { b.x = W - R; b.vx = -Math.abs(b.vx) * WALL_E; }
          if (b.y < R) { b.y = R; b.vy = Math.abs(b.vy) * WALL_E; }
          else if (b.y > H - R) { b.y = H - R; b.vy = -Math.abs(b.vy) * WALL_E; }
        }
      }
      draw();
    },
    state: function() {
      return internalBalls.map(b => ({
        x: b.x,
        y: b.y,
        vx: b.vx,
        vy: b.vy,
        potted: b.potted,
        cue: b.cue
      }));
    },
    shoot: function(vx, vy) {
      let cue = internalBalls.find(b => b.cue);
      if (cue && !cue.potted) {
        cue.vx = vx;
        cue.vy = vy;
      }
    },
    pause: function() {
      if (animId !== null) {
        cancelAnimationFrame(animId);
        animId = null;
      }
    },
    resume: function() {
      if (animId === null) {
        lastTime = null;
        animId = requestAnimationFrame(loop);
      }
    }
  };

  function getMousePos(e) {
    let rect = canvas.getBoundingClientRect();
    let scaleX = canvas.width / rect.width;
    let scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX - OFFSET,
      y: (e.clientY - rect.top) * scaleY - OFFSET
    };
  }

  canvas.addEventListener('mousedown', e => {
    let pos = getMousePos(e);
    let cue = internalBalls.find(b => b.cue && !b.potted);
    if (!cue) return;
    if (Math.hypot(pos.x - cue.x, pos.y - cue.y) < R * 3) {
      isDragging = true;
      dragCurrent = pos;
      draw();
    }
  });

  window.addEventListener('mousemove', e => {
    if (!isDragging) return;
    dragCurrent = getMousePos(e);
    draw();
  });

  window.addEventListener('mouseup', e => {
    if (!isDragging) return;
    isDragging = false;
    let cue = internalBalls.find(b => b.cue && !b.potted);
    if (cue && dragCurrent) {
      let dx = cue.x - dragCurrent.x;
      let dy = cue.y - dragCurrent.y;
      let dist = Math.hypot(dx, dy);
      if (dist > 0) {
        let power = Math.min(dist, MAX_DRAG) / MAX_DRAG;
        let speed = power * MAX_SPEED;
        window.sim.shoot(dx / dist * speed, dy / dist * speed);
      }
    }
    dragCurrent = null;
    draw();
  });

  function rackBalls() {
    let balls = [];
    balls.push({x: W * 0.25, y: H / 2, cue: true});
    let startX = W * 0.7;
    let startY = H / 2;
    let gap = R * 2 + 0.5;
    for (let row = 0; row < 5; row++) {
      for (let col = 0; col <= row; col++) {
        let x = startX + row * gap * Math.sqrt(3)/2;
        let y = startY + (col - row/2) * gap;
        balls.push({x: x, y: y});
      }
    }
    window.sim.reset(balls);
  }

  document.getElementById('reset-btn').addEventListener('click', rackBalls);

  function loop(time) {
    if (lastTime === null) lastTime = time;
    let dt = (time - lastTime) / 1000;
    lastTime = time;
    if (dt > 0.1) dt = 0.1;
    window.sim.step(dt);
    animId = requestAnimationFrame(loop);
  }

  // Initialize game
  rackBalls();
  window.sim.resume();
})();
</script>
</body>
